package com.example.shop.domain;

import jakarta.persistence.Entity;
import jakarta.persistence.Id;

@Entity
public class Gadget {

    @Id
    private Long id;

    private String name;

    private String color;
}

package com.example.shop.dto;

/** Summary of {@link com.example.shop.domain.Gadget}. */
public record GadgetSummary(
        Long id,
        String name
) {
}

package com.example.shop.dto;

/** Something else. */
public record GadgetOther(Long id, String name) {
}

package com.example.shop.dto;

public interface GadgetProjection {
    Long getId();
    String getName();
}
